#include <stdio.h>
void swap(char c[],int r)
{
    char t[r];
    if(r%2==0)
    {
        for(int i=0;i<r/2;i++)
        {
            t[i]=c[i+r/2];
        }
        for(int j=r/2;j<r;j++)
        {
            t[j]=c[j-r/2];
        }
    }
    else
    {
        for(int i=0;i<r/2;i++)
        {
            t[i]=c[i+r/2+1];
        }
        for(int j=r/2+1;j<r;j++)
        {
            t[j]=c[j-r/2-1];
        }
        t[r/2]=c[r/2];
    }
    //t[r]='\0';
    printf("%s",t);
}
